import pathModule from "node:path";
import fsExtra from "fs-extra";
import { IFileItem, TProgressCallback } from "./types";

export function removeFiles(dir: string, deleteList: Array<IFileItem> = [], pc?: TProgressCallback) {
  // 删除文件
  deleteList.forEach((fileItem, index) => {
    const deletePath = pathModule.join(dir, fileItem.path);
    if (fsExtra.existsSync(deletePath)) {
      fsExtra.unlink(deletePath, (error) => {
        if (error) throw error;
      });
    }
    pc?.(Math.round(((index + 1) / deleteList.length) * 100));
  });
}
